//! 混合生成：`exit-codes.md` / `error-codes.md` §A 整表（contract-governance-04-specgen-rebuild）。
//!
//! 把 `enum_source` 的机器可导出列（退出码数值 / 错误码串 + 对应退出码）与 spec-gen 侧维护的
//! 中文叙述映射表（类别 / 含义 / 固化切片）拼接成 §A 整表。机器列由 enum 迭代器生成并受
//! drift 门禁锁定（手改即红）；叙述列来自本地映射表，人读叙述，drift 门禁只锁机器列。
//!
//! 边界（CLAUDE.md §3/§8）：spec-gen 是 dev-only xtask，只读 novel-cli enum 源与本地叙述
//! 映射表，不读 SQLite、不读 `.novel/content`，无运行期世界状态。

use crate::enum_source::EnumSourceMaps;

/// 生成段起始标记前缀（`<!-- @generated by spec-gen ... -->`）。
pub const GEN_MARKER_PREFIX: &str = "<!-- @generated by spec-gen";
/// 生成段结束标记。
pub const GEN_END: &str = "<!-- /@generated -->";

/// 退出码叙述：数值 → 类别（中文，供 ssot 归一映射与整表渲染共用）。
pub fn exit_category(code: i32) -> Option<&'static str> {
    exit_narrative(code).map(|(c, _, _)| c)
}

/// 退出码叙述：数值 → (类别, 含义, 固化切片)。逐字取自现手写 `exit-codes.md` §A。
fn exit_narrative(code: i32) -> Option<(&'static str, &'static str, &'static str)> {
    Some(match code {
        0 => ("成功", "命令成功完成其操作。", "cli-spine-init-info"),
        2 => ("用法/参数错误", "非法或缺失的参数、非法枚举值、路径参数非法。", "cli-spine-init-info"),
        3 => ("前置条件阻断", "命令所需的世界状态不满足（如未初始化、状态机不允许）。", "cli-spine-init-info"),
        4 => ("资源冲突", "资源已存在而拒绝操作（如 `.novel/` 已存在、约束重复定义）。", "cli-spine-init-info"),
        5 => ("状态冲突", "检测到状态不一致或版本冲突（如 `contentHash` 不匹配、stale 检查结果）。", "s03-rule-checking-engine"),
        6 => ("数据不存在或引用无效", "查询不存在的实体 ID（如 `setting get <不存在>`、`constraint render <不存在>`）。", "s01-project-bootstrap"),
        11 => ("文件不存在", "输入文件或正文文件不存在。", "s02-chapter-content-core"),
        20 => ("章节不存在", "章节 ID 不存在。", "s02-chapter-content-core"),
        21 => ("内容已被外部修改", "检测到正文 hash 不匹配，文件已被外部修改。", "s02-chapter-content-core"),
        41 => ("非法状态转换", "涌现状态机转换非法（如跳过阶段、后退、重复）。", "s06-destiny-weaving"),
        42 => ("线索名称冲突", "同一卷内线索名称重复。", "s06-destiny-weaving"),
        43 => ("主线节点不存在", "主线节点 ID 不存在。", "s06-destiny-weaving"),
        44 => ("线索不存在", "线索 ID 不存在。", "s06-destiny-weaving"),
        45 => ("涌现不存在", "涌现 ID 不存在。", "s06-destiny-weaving"),
        46 => ("绑定已存在", "同一线索与章节的组合已绑定。", "s06-destiny-weaving"),
        47 => ("涌现已归档", "不可修改已归档的涌现。", "s06-destiny-weaving"),
        70 => ("内部/存储错误", "内部异常、存储读写失败、迁移失败。", "cli-spine-init-info"),
        _ => return None,
    })
}

/// 错误码叙述：错误码串 → (含义, 固化切片)。逐字取自现手写 `error-codes.md`（§A 通用码 +
/// 卷管理细分 + s06 细分 + 细分错误码各表）。
pub fn has_error_narrative(code: &str) -> bool {
    error_narrative(code).is_some()
}

/// 错误码叙述：错误码串 → (含义, 固化切片)。逐字取自现手写 `error-codes.md`（§A 通用码 +
/// 卷管理细分 + s06 细分 + 细分错误码各表）。
fn error_narrative(code: &str) -> Option<(&'static str, &'static str)> {
    Some(match code {
        "usage" => ("非法或缺失的参数、非法枚举值、路径参数非法。", "cli-spine-init-info"),
        "precondition_blocked" => ("命令所需的世界状态不满足（如未初始化、状态机不允许）。", "cli-spine-init-info"),
        "resource_conflict" => ("资源已存在而拒绝操作（如 `.novel/` 已存在、约束重复定义）。", "cli-spine-init-info"),
        "external_modification" => ("检测到绕过 CLI 的外部修改（正文 hash 不匹配等）。", "cli-spine-init-info"),
        "not_found" => ("查询不存在的实体（如配置项、约束规则）。", "s01-project-bootstrap"),
        "storage" => ("内部异常、存储读写失败、迁移失败。", "cli-spine-init-info"),
        "setting_not_found" => ("指定的配置项不存在。", "s01-project-bootstrap"),
        "constraint_not_found" => ("指定的约束规则不存在。", "s01-project-bootstrap"),
        "constraint_already_exists" => ("同 `(type, scope, name)` 的约束已存在。", "s01-project-bootstrap"),
        "world_not_initialized" => ("世界未初始化（`.novel/` 不存在）。", "cli-spine-init-info"),
        "chapter_not_found" => ("章节 ID 不存在。", "s02-chapter-content-core"),
        "content_modified_externally" => ("正文文件已被外部修改（hash 失配）。", "s02-chapter-content-core"),
        "file_not_found" => ("输入文件或正文文件不存在。", "s02-chapter-content-core"),
        "invalid_content" => ("章节正文输入文件非 UTF-8 文本（编码或格式不可解析）。", "s02-chapter-content-core"),
        "content_hash_mismatch" => ("输入 JSON 中的 `contentHash` 与章节当前正文 hash 不匹配。", "s03-rule-checking-engine"),
        "stale_rule_checks" => ("检查结果已过期（正文已修改），`--verify-hash` 验证失败。", "s03-rule-checking-engine"),
        "invalid_input" => ("输入 JSON 格式错误或缺少必填字段。", "s03-rule-checking-engine"),
        "volume_not_found" => ("指定的卷不存在。", "s05-volume-management"),
        "volume_already_sealed" => ("卷已封闭，拒绝重复封卷或在 sealing/sealed 卷下新增/修改下属实体。", "s05-volume-management"),
        "chapters_not_approved" => ("卷内存在非 `approved` 状态的章节，阻断封卷。", "s05-volume-management"),
        "emergences_not_handled" => ("卷内存在未处置的涌现（`pending`/`rated`/`decided`），阻断封卷。", "s05-volume-management"),
        "goals_not_achieved" => ("卷的必达目标对应主线节点未 `achieved=1`，阻断封卷。", "s05-volume-management"),
        "volume_not_sealed" => ("卷状态非 `sealed`，拒绝归档。", "s05-volume-management"),
        "volume_already_archived" => ("卷已归档，拒绝任何修改其卷属性或下属实体的写操作。", "s05-volume-management"),
        "invalid_state_transition" => ("涌现状态机转换非法（跳过阶段、后退、重复）。", "s06-destiny-weaving"),
        "thread_name_conflict" => ("同一卷内线索名称重复。", "s06-destiny-weaving"),
        "mainplot_node_not_found" => ("主线节点 ID 不存在。", "s06-destiny-weaving"),
        "thread_not_found" => ("线索 ID 不存在。", "s06-destiny-weaving"),
        "emergence_not_found" => ("涌现 ID 不存在。", "s06-destiny-weaving"),
        "binding_already_exists" => ("同一线索与章节的组合已绑定。", "s06-destiny-weaving"),
        "emergence_archived" => ("不可修改已归档的涌现。", "s06-destiny-weaving"),
        "context_budget_exceeded" => ("上下文预算不足以装填必需 P0/P1_min 片段（可恢复——调高 `--budget` 或拆章）。", "chapter-context-packet"),
        "state_conflict" => ("检测到状态不一致或版本冲突（如 `contentHash` 不匹配、stale 检查结果）。", "s03-rule-checking-engine"),
        _ => return None,
    })
}

/// 渲染 `exit-codes.md` §A 生成段（标记 + 整表）。
pub fn render_exit_codes_block(maps: &EnumSourceMaps) -> String {
    let mut s = String::new();
    s.push_str("<!-- @generated by spec-gen enum_source. DO NOT EDIT. -->\n");
    s.push_str("<!-- 退出码数值（机器列）唯一源：novel_cli::errors::ExitCode 判别式；类别/含义/固化切片（叙述列）来自 spec-gen 侧映射表，人可手改（drift 只锁机器列）。 -->\n");
    s.push_str("| 退出码 | 类别 | 含义 | 固化切片 |\n");
    s.push_str("|---|---|---|---|\n");
    for e in &maps.exit_codes {
        let (cat, meaning, slice) = exit_narrative(e.code).unwrap_or(("（缺叙述）", "（缺叙述）", "（缺叙述）"));
        s.push_str(&format!("| `{}` | {} | {} | `{}` |\n", e.code, cat, meaning, slice));
    }
    s.push_str(GEN_END);
    s.push('\n');
    s
}

/// 渲染 `error-codes.md` §A 生成段（标记 + 整表）。
pub fn render_error_codes_block(maps: &EnumSourceMaps) -> String {
    let mut s = String::new();
    s.push_str("<!-- @generated by spec-gen enum_source. DO NOT EDIT. -->\n");
    s.push_str("<!-- 错误码字符串 / 对应退出码（机器列）唯一源：novel_cli::errors::ErrorCode strum serialize + spec-gen aliases；含义/固化切片（叙述列）来自 spec-gen 侧映射表，人可手改（drift 只锁机器列）。 -->\n");
    s.push_str("| 错误码 | 含义 | 对应退出码 | 固化切片 |\n");
    s.push_str("|---|---|---|---|\n");
    for e in &maps.error_codes {
        let (meaning, slice) = error_narrative(e.code).unwrap_or(("（缺叙述）", "（缺叙述）"));
        s.push_str(&format!("| `{}` | {} | `{}` | `{}` |\n", e.code, meaning, e.stated_exit, slice));
    }
    s.push_str(GEN_END);
    s.push('\n');
    s
}

/// 从 §A 表格中提取机器列签名（仅机器列，供 drift 比对；叙述列手改不触发 drift）。
///
/// `cols` 为机器列的下标（0-based）：exit 为 `[0]`（退出码）；error 为 `[0, 2]`（错误码、对应退出码）。
fn machine_signature(block: &str, cols: &[usize]) -> String {
    let mut sig = String::new();
    for line in block.lines() {
        let line = line.trim();
        if !line.starts_with('|') {
            continue;
        }
        let cells: Vec<&str> = line.split('|').collect();
        let mut parts: Vec<&str> = Vec::new();
        for &c in cols {
            parts.push(cells.get(c + 1).map(|s| s.trim()).unwrap_or(""));
        }
        sig.push_str(&parts.join("|"));
        sig.push('\n');
    }
    sig
}

/// 从文件内容中提取首个生成段（`<!-- @generated ... -->` 到 `<!-- /@generated -->`）。
///
/// 返回 `(start_idx, end_idx, block_content)`；无生成段返回 `None`。
fn extract_block(content: &str) -> Option<(usize, usize, String)> {
    let start = content.find(GEN_MARKER_PREFIX)?;
    let end_marker = content[start..].find(GEN_END)?;
    let end_abs = start + end_marker;
    let end_abs = end_abs + GEN_END.len();
    let block = content[start..end_abs].to_string();
    Some((start, end_abs, block))
}

/// 在文件内容中定位 §A 表格首行（`## §A 生效契约码` 之后的首个 `|` 行），返回该行下标。
fn find_a_table_start(lines: &[&str]) -> Option<usize> {
    let mut in_a = false;
    for (i, line) in lines.iter().enumerate() {
        if line.trim_start().starts_with("## §A") {
            in_a = true;
            continue;
        }
        if in_a {
            if line.trim_start().starts_with("## §B") || line.trim_start().starts_with("### ") {
                return None; // §A 表尚未找到即遇到下一节，异常
            }
            if line.trim_start().starts_with('|') {
                return Some(i);
            }
        }
    }
    None
}

/// 找到连续表格行（以 `|` 开头）的结束下标（不含）。
fn table_end(lines: &[&str], start: usize) -> usize {
    let mut end = start;
    while end < lines.len() && lines[end].trim_start().starts_with('|') {
        end += 1;
    }
    end
}

/// 生成（替换/注入）单个 md 文件的 §A 生成段。
///
/// 有生成段标记则替换标记内内容；无标记则把 `## §A` 后的整表替换为生成块。
pub fn apply_a_table(path: &std::path::Path, block: String) -> anyhow::Result<()> {
    let content = std::fs::read_to_string(path)?;
    let new_content = if extract_block(&content).is_some() {
        let (start, end, _) = extract_block(&content).unwrap();
        let mut s = String::new();
        s.push_str(&content[..start]);
        s.push_str(&block);
        s.push_str(&content[end..]);
        s
    } else {
        let lines: Vec<&str> = content.lines().collect();
        let start = find_a_table_start(&lines)
            .ok_or_else(|| anyhow::anyhow!("{} 未找到 §A 表格", path.display()))?;
        let end = table_end(&lines, start);
        let mut out = String::new();
        for (i, line) in lines.iter().enumerate() {
            if i == start {
                out.push_str(&block);
            }
            if i < start || i >= end {
                out.push_str(line);
                out.push('\n');
            }
        }
        // 若表格行是文件末尾（无后续内容），补换行。
        out
    };
    if new_content != content {
        std::fs::write(path, new_content)?;
    }
    Ok(())
}

/// 校验 §A 机器列 drift。返回 `true` 表示漂移。
pub fn check_a_drift(path: &std::path::Path, expected_block: &str, cols: &[usize]) -> bool {
    let on_disk = std::fs::read_to_string(path).unwrap_or_default();
    let Some((_, _, block)) = extract_block(&on_disk) else {
        // 无生成段标记：视为漂移（未生成或手删标记）。
        return true;
    };
    machine_signature(&block, cols) != machine_signature(expected_block, cols)
}
